<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import NavbarContrato from '@/Pages/Sgc/Contratada/NavbarContrato.vue';
import Breadcrumb from '@/Components/Breadcrumb.vue';
import { ref } from 'vue';
import { useForm } from '@inertiajs/vue3';
import PlanilhasSimplificadasVisualizar from './PlanilhasSimplificadasVisualizar.vue';
const props = defineProps({ campanha: Object, contrato: [Number, String], produto: String, contratos: Object, canApprove: Boolean, analises: Array });
const form = useForm({ observacoes: '' }); const reprovar = ref(false);
const aprovar = () => form.post(route('sgc.contratada.produtos.fauna.simplificada.aprovar', [props.contrato, 'fauna', props.campanha.id]));
const confirmarReprovacao = () => form.post(route('sgc.contratada.produtos.fauna.simplificada.reprovar', [props.contrato, 'fauna', props.campanha.id]), { onSuccess: () => { reprovar.value = false; form.reset(); } });
</script>
<template><AuthenticatedLayout><template #header><Breadcrumb :links="[{ route: route('sgc.gestao.listagem', props.contratos.tipo_contrato), label: 'Gestão de Contratos' }, { route: route('sgc.contratada.produtos.index', [props.contrato, 'fauna']), label: props.contratos.contratada }, { route: '#', label: 'Analisar campanha simplificada de Fauna' }]" /></template><NavbarContrato :tipo="{ id: props.contrato }"><template #body><div class="card"><div class="card-body"><div class="text-center mb-4"><h2 class="mb-2">ANÁLISE CAMPANHA SIMPLIFICADA DE FAUNA</h2><p class="text-muted mb-0">{{ campanha.subproduto }}</p></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="info-box"><span>Campanha</span><strong>{{ campanha.id_campanha || 'N/A' }}</strong></div></div><div class="col-md-3"><div class="info-box"><span>Empreendimento</span><strong>{{ campanha.cod_emp || 'N/A' }}</strong></div></div><div class="col-md-3"><div class="info-box"><span>SEI DNIT</span><strong>{{ campanha.sei_dnit || 'N/A' }}</strong></div></div><div class="col-md-3"><div class="info-box"><span>Status</span><strong>{{ campanha.status || 'N/A' }}</strong></div></div></div><PlanilhasSimplificadasVisualizar :planilhas="campanha.planilhas" /><section class="mt-4"><h4 class="section-title">Fotos</h4><div v-if="campanha.fotos?.length" class="photo-grid"><a v-for="foto in campanha.fotos" :key="foto.id" :href="foto.url" target="_blank" class="photo-card"><img v-if="foto.url" :src="foto.url"><div class="photo-meta"><strong>{{ foto.nome_arquivo || 'Foto' }}</strong><span v-if="foto.descricao">{{ foto.descricao }}</span></div></a></div><div v-else class="empty-state">Nenhuma foto vinculada.</div></section><section class="mt-4"><h4 class="section-title">Anexos</h4><div v-if="campanha.anexos?.length" class="list-group"><a v-for="anexo in campanha.anexos" :key="anexo.id" :href="anexo.url" target="_blank" rel="noopener" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center"><span>{{ anexo.nome_arquivo || 'Anexo' }}</span><span class="text-primary">Abrir</span></a></div><div v-else class="empty-state">Nenhum anexo vinculado.</div></section><section class="mt-4 pt-3 border-top"><h4 class="section-title">Decisão da análise</h4><button type="button" class="btn btn-success me-2" :disabled="form.processing" @click="aprovar">Aprovar</button><button type="button" class="btn btn-outline-danger" @click="reprovar = !reprovar">Reprovar</button><div v-if="reprovar" class="mt-3"><textarea v-model="form.observacoes" class="form-control mb-2" rows="4" placeholder="Justificativa (mínimo 10 caracteres)"></textarea><small v-if="form.errors.observacoes" class="text-danger d-block mb-2">{{ form.errors.observacoes }}</small><button type="button" class="btn btn-danger" :disabled="form.processing || form.observacoes.length < 10" @click="confirmarReprovacao">Confirmar reprovação</button></div></section><section v-if="analises?.length" class="mt-4"><h4 class="section-title">Histórico</h4><div v-for="analise in analises" :key="analise.id" class="border rounded p-2 mb-2"><strong>Versão {{ analise.versao_analise }}</strong> — {{ analise.status }}<br><small>{{ analise.fiscal?.name }} · {{ analise.created_at }}</small><div v-if="analise.observacoes">{{ analise.observacoes }}</div></div></section></div></div></template></NavbarContrato></AuthenticatedLayout></template>
<style scoped>.info-box { border: 1px solid #e2e4e6; border-radius: 6px; padding: 12px; min-height: 82px; }.info-box span { display: block; color: #6c757d; font-size: .85rem; margin-bottom: 6px; }.info-box strong { overflow-wrap: anywhere; }.section-title { font-size: 1.05rem; font-weight: 700; margin-bottom: 12px; }.photo-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 14px; }.photo-card { border: 1px solid #e2e4e6; border-radius: 8px; overflow: hidden; color: inherit; text-decoration: none; }.photo-card img { width: 100%; height: 145px; object-fit: cover; display: block; }.photo-meta { padding: 10px; font-size: .8rem; display: flex; flex-direction: column; gap: 3px; }.empty-state { border: 1px dashed #c9ced3; border-radius: 6px; color: #6c757d; padding: 16px; text-align: center; }</style>
